import random

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp = [h[1] for h in history]
    own = [h[0] for h in history]

    def streak(seq, ch):
        s = 0
        for x in reversed(seq):
            if x == ch:
                s += 1
            else:
                break
        return s

    op_d = sum(1 for o in opp if o == 'D')
    my_d = sum(1 for o in own if o == 'D')
    last_op = opp[-1]
    op_d_streak = streak(opp, 'D')
    remaining = 100 - n

    # Endgame: push for defection advantage when close to the end.
    if remaining <= 2:
        return 'D'

    if n < 6:
        return 'C'

    # If we've defected much more than opponent (being greedy), re-cooperate
    # periodically to preserve mutual cooperation value against reciprocators.
    if op_d_streak >= 2:
        if op_d_streak >= 5:
            return 'D'
        if last_op == 'D':
            if rng.random() < 0.15:
                return 'C'
            return 'D'
        return 'D'

    # Opponent just defected once.
    if last_op == 'D':
        op_rate_early = op_d / float(n)
        if op_rate_early > 0.5:
            return 'D'
        if rng.random() < 0.25:
            return 'C'
        return 'D'

    # Opponent just cooperated.
    op_rate = op_d / float(n)

    # Detect run-heavy patterns.
    last4 = opp[-4:]
    if op_d_streak == 0 and n >= 4 and my_d == 0 and op_d == 0:
        # Pure cooperator detected: exploit significantly but keep some
        # cooperation so we don't snap them out of it.
        if remaining > 10 and rng.random() < 0.55:
            return 'D'
        return 'C'

    # Mostly cooperative opponent.
    if op_rate < 0.15:
        if remaining <= 6:
            return 'D'
        # Occasionally exploit and occasionally test if we're too nice.
        if my_d > op_d + 2 and rng.random() < 0.4:
            return 'C'
        if rng.random() < 0.10:
            return 'D'
        return 'C'

    # Moderately cooperative.
    if op_rate < 0.35:
        if rng.random() < 0.08:
            return 'D'
        return 'C'

    # Highly defective opponent: defect mostly.
    if op_rate >= 0.6:
        if rng.random() < 0.05:
            return 'C'
        return 'D'

    # Middle zone: mostly cooperate with some probing.
    if rng.random() < 0.15:
        return 'D'
    return 'C'
